function getTodayQ(qs) {
  if (!qs.length) return null;
  const d = Math.floor((Date.now() - new Date(new Date().getFullYear(),0,0)) / 86400000);
  return qs[d % qs.length];
}

function Particles() {
  const ref = useRef(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const ctx = c.getContext("2d");
    let W = c.width = window.innerWidth, H = c.height = window.innerHeight;
    const onR = () => { W = c.width = window.innerWidth; H = c.height = window.innerHeight; };
    window.addEventListener("resize", onR);
    const pts = Array.from({length:40}, () => ({
      x:Math.random()*W, y:Math.random()*H, r:Math.random()*1.5+.3,
      vx:(Math.random()-.5)*.18, vy:(Math.random()-.5)*.18,
      a:Math.random()*.25+.04, gold:Math.random()>.5
    }));
    let raf;
    const draw = () => {
      ctx.clearRect(0,0,W,H);
      pts.forEach(p => {
        p.x+=p.vx; p.y+=p.vy;
        if(p.x<0)p.x=W; if(p.x>W)p.x=0; if(p.y<0)p.y=H; if(p.y>H)p.y=0;
        ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
        ctx.fillStyle = p.gold ? "rgba(201,169,110,"+p.a+")" : "rgba(160,140,100,"+(p.a*.5)+")";
        ctx.fill();
      });
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize",onR); };
  },[]);
  return React.createElement("canvas", {ref, style:{position:"absolute",inset:0,pointerEvents:"none",zIndex:0}});
}

function Reveal({children, delay=0}) {
  const ref = useRef(null);
  const [v,setV] = useState(false);
  useEffect(() => {
    const o = new IntersectionObserver(([e])=>{if(e.isIntersecting)setV(true)},{threshold:.07});
    if(ref.current) o.observe(ref.current);
    return ()=>o.disconnect();
  },[]);
  return (
    <div ref={ref} style={{opacity:v?1:0, transform:v?"translateY(0)":"translateY(36px)", transition:"opacity 0.85s ease "+delay+"s, transform 0.85s cubic-bezier(0.23,1,0.32,1) "+delay+"s"}}>
      {children}
    </div>
  );
}

