// ── ANNOUNCEMENT BANNER (top sticky) ────────────────────────────────────────
function AnnouncementBanner({announcements, onDismiss}) {
  const urgent = announcements.filter(a => a.urgent);
  const [idx, setIdx] = useState(0);
  const [dismissed, setDismissed] = useState(false);
  useEffect(() => {
    if(urgent.length <= 1) return;
    const t = setInterval(() => setIdx(i => (i+1) % urgent.length), 4000);
    return () => clearInterval(t);
  }, [urgent.length]);
  if(!urgent.length || dismissed) return null;
  const a = urgent[idx % urgent.length];
  const t = ANNOUNCE_TYPES[a.type] || ANNOUNCE_TYPES.general;
  return (
    <div style={{position:"relative",width:"100%",zIndex:200,background:"linear-gradient(90deg,#0a0f1a,#0f1a2e,#0a0f1a)",borderBottom:"1px solid "+t.color+"44",padding:"10px 4%",display:"flex",alignItems:"center",justifyContent:"space-between",gap:14}}>
      <div style={{display:"flex",alignItems:"center",gap:12,flex:1,minWidth:0}}>
        <span style={{fontSize:16,flexShrink:0}}>{t.icon}</span>
        <span style={{fontSize:10,color:t.color,letterSpacing:2,textTransform:"uppercase",flexShrink:0,background:t.bg,padding:"3px 9px",borderRadius:2,border:"1px solid "+t.color+"33"}}>{t.label}</span>
        <span style={{fontSize:13,color:"#e8d5b8",fontFamily:"'Cormorant Garamond',serif",fontStyle:"italic",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{a.title}</span>
        {a.link && <a href={a.link} target="_blank" rel="noreferrer" style={{fontSize:11,color:t.color,letterSpacing:2,textTransform:"uppercase",textDecoration:"none",flexShrink:0,borderBottom:"1px solid "+t.color+"55",paddingBottom:1,transition:"opacity .3s"}} onMouseEnter={e=>e.target.style.opacity=".7"} onMouseLeave={e=>e.target.style.opacity="1"}>{a.linkLabel||"Learn More"} →</a>}
      </div>
      <button onClick={()=>setDismissed(true)} style={{background:"none",border:"none",cursor:"pointer",color:"#5a4a2a",fontSize:16,flexShrink:0,padding:"0 4px",lineHeight:1}} title="Dismiss">×</button>
    </div>
  );
}

