  const [tab,setTab]=useState("announcements");
  const [nq,setNq]=useState(""); const [np,setNp]=useState({title:"",date:"",text:""});
  const [na,setNa]=useState({type:"general",title:"",message:"",date:"",link:"",linkLabel:"",urgent:false});
  const [saving,setSaving]=useState(false); const [msg,setMsg]=useState("");

  const showMsg=m=>{setMsg(m);setTimeout(()=>setMsg(""),2500);};

  const doAddQ=async()=>{ if(!nq.trim())return; setSaving(true); await onAddQ(nq.trim()); setNq(""); setSaving(false); showMsg("Quote published!"); };
  const doAddP=async()=>{ if(!np.title.trim()||!np.text.trim())return; setSaving(true); await onAddP({...np,date:np.date||new Date().toLocaleDateString("en-US",{month:"long",year:"numeric"})}); setNp({title:"",date:"",text:""}); setSaving(false); showMsg("Poem published!"); };
  const doAddA=async()=>{ if(!na.title.trim()||!na.message.trim())return; setSaving(true); await onAddA({...na,date:na.date||new Date().toLocaleDateString("en-US",{month:"long",year:"numeric"})}); setNa({type:"general",title:"",message:"",date:"",link:"",linkLabel:"",urgent:false}); setSaving(false); showMsg("Announcement published!"); };

